class Solution {
    public List<String> cellsInRange(String s) {
        List<String> result = new java.util.ArrayList<>();
        char c1 = s.charAt(0), r1 = s.charAt(1);
        char c2 = s.charAt(3), r2 = s.charAt(4);
        for (char c = c1; c <= c2; c++) {
            for (char r = r1; r <= r2; r++) {
                result.add("" + c + r);
            }
        }
        return result;
    }
}

import java.util.List;
import java.util.ArrayList;

class Solution {
    public List<String> cellsInRange(String s) {
        List<String> result = new ArrayList<>();
        char colStart = s.charAt(0), rowStart = s.charAt(1);
        char colEnd = s.charAt(3), rowEnd = s.charAt(4);
        for (char col = colStart; col <= colEnd; col++) {
            for (char row = rowStart; row <= rowEnd; row++) {
                StringBuilder sb = new StringBuilder();
                sb.append(col);
                sb.append(row);
                result.add(sb.toString());
            }
        }
        return result;
    }
}
